    if (p.ptms && p.ptms.length) ov['p-ptm'] = { vis: aTrack(len, [{ label: 'PTMs', items: p.ptms.map(([q, g]) => ({ a: q, b: q, cls: 'ptm', tip: PTM_LABEL[g] + ' ' + q })) }, { label: 'Sites', items: pins('site') }]) };
