      for (const s of hits) g += titled(MARK.ring(X(s.pos), cy, 4.2, ln.color, !!ln.hollow, ' fill="' + pal.bg + '"').replace('fill="none" ', ''), p.label + ' ' + rl(s.pos, P[s.p]) + ': ' + ln.label + ' at this methylarginine');
