        '<text x="' + (W - colN - 14) + '" y="' + r1(cy + 4) + '" font-size="11" text-anchor="end" fill="' + pal.ink + '">' + (r.q == null ? '–' : fmtP(r.q)) + '</text>' +
        '<text x="' + (W - 8) + '" y="' + r1(cy + 4) + '" font-size="11" text-anchor="end" fill="' + pal.muted + '">' + fmt(r.used) + '/' + fmt(r.proteins) + '</text>';
